CREATE TABLE requisition_recruiter_supports(requisition_id TEXT NOT NULL REFERENCES requisitions(id),user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(requisition_id,user_id));
CREATE INDEX recruiter_support_user ON requisition_recruiter_supports(user_id,requisition_id);
CREATE TRIGGER recruiter_support_not_primary BEFORE INSERT ON requisition_recruiter_supports WHEN EXISTS(SELECT 1 FROM requisitions WHERE id=NEW.requisition_id AND recruiter_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'DUPLICATE_RECRUITER_ASSIGNMENT');END;
CREATE TRIGGER recruiter_support_update_not_primary BEFORE UPDATE ON requisition_recruiter_supports WHEN EXISTS(SELECT 1 FROM requisitions WHERE id=NEW.requisition_id AND recruiter_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'DUPLICATE_RECRUITER_ASSIGNMENT');END;
CREATE TRIGGER recruiter_primary_not_support BEFORE UPDATE OF recruiter_id ON requisitions WHEN EXISTS(SELECT 1 FROM requisition_recruiter_supports WHERE requisition_id=NEW.id AND user_id=NEW.recruiter_id) BEGIN SELECT RAISE(ABORT,'DUPLICATE_RECRUITER_ASSIGNMENT');END;
CREATE TABLE requisition_assignment_versions(requisition_id TEXT PRIMARY KEY REFERENCES requisitions(id),version INTEGER NOT NULL CHECK(version>=0));
CREATE TABLE requisition_recruiter_events(id TEXT PRIMARY KEY,requisition_id TEXT NOT NULL REFERENCES requisitions(id),version INTEGER NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,changes_json TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(requisition_id,version));
CREATE TABLE requisition_operation_requests(actor_id TEXT NOT NULL,request_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('COPY','ASSIGN')),fingerprint TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(actor_id,request_id));
CREATE TRIGGER recruiter_events_no_update BEFORE UPDATE ON requisition_recruiter_events BEGIN SELECT RAISE(ABORT,'RECRUITER_HISTORY_IMMUTABLE');END;
CREATE TRIGGER recruiter_events_no_delete BEFORE DELETE ON requisition_recruiter_events BEGIN SELECT RAISE(ABORT,'RECRUITER_HISTORY_IMMUTABLE');END;
CREATE TRIGGER operation_requests_no_update BEFORE UPDATE ON requisition_operation_requests BEGIN SELECT RAISE(ABORT,'OPERATION_RECEIPT_IMMUTABLE');END;
CREATE TRIGGER operation_requests_no_delete BEFORE DELETE ON requisition_operation_requests BEGIN SELECT RAISE(ABORT,'OPERATION_RECEIPT_IMMUTABLE');END;
